package com.fream.back.visible.t05;

import com.fream.back.domain.order.entity.BidStatus;
import com.fream.back.domain.order.entity.Order;
import com.fream.back.domain.order.entity.OrderBid;
import com.fream.back.domain.order.entity.OrderStatus;
import com.fream.back.domain.product.entity.Product;
import com.fream.back.domain.product.entity.ProductColor;
import com.fream.back.domain.product.entity.ProductSize;
import com.fream.back.domain.product.entity.enumType.GenderType;
import com.fream.back.domain.product.entity.enumType.SizeType;
import com.fream.back.domain.sale.entity.Sale;
import com.fream.back.domain.sale.entity.SaleBid;
import com.fream.back.domain.sale.entity.SaleStatus;
import com.fream.back.domain.shipment.entity.OrderShipment;
import com.fream.back.domain.shipment.entity.ShipmentStatus;
import com.fream.back.domain.shipment.service.command.OrderShipmentCommandService;
import com.fream.back.domain.user.entity.Point;
import com.fream.back.domain.user.entity.User;
import com.fream.back.global.config.QueryDslConfig;
import jakarta.persistence.EntityManager;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.jdbc.AutoConfigureTestDatabase;
import org.springframework.boot.test.autoconfigure.orm.jpa.DataJpaTest;
import org.springframework.context.ApplicationContext;
import org.springframework.context.annotation.Import;
import org.springframework.test.context.ActiveProfiles;

import java.util.List;

import static org.assertj.core.api.Assertions.assertThat;

/**
 * 배송 완료 시 구매 금액의 1%가 구매자에게 포인트로 적립되는지 본다.
 */
@DataJpaTest
@AutoConfigureTestDatabase(replace = AutoConfigureTestDatabase.Replace.NONE)
@ActiveProfiles("test")
@Import(QueryDslConfig.class)
class PurchaseRewardTest {

    @Autowired EntityManager em;
    @Autowired ApplicationContext ctx;

    private static int seq = 0;

    private User user(String email) {
        seq++;
        User u = User.builder().email(email).password("pw").referralCode("v5-" + seq)
                .phoneNumber("010-5000-" + seq).build();
        em.persist(u);
        return u;
    }

    /** 배송 중인 주문 하나(판매 입찰·구매 입찰이 연결된 상태)를 만들고 주문 ID를 돌려준다. */
    private Long orderInTransit(User buyer, User seller, int totalAmount) {
        Product product = Product.builder().name("덩크 로우").englishName("Dunk Low").releasePrice(139000)
                .modelNumber("DD-" + seq).releaseDate("2024-01-01").gender(GenderType.UNISEX).build();
        em.persist(product);
        ProductColor color = ProductColor.builder().colorName("Panda").product(product).build();
        em.persist(color);
        ProductSize size = ProductSize.builder().sizeType(SizeType.SHOES).size("270")
                .purchasePrice(totalAmount).salePrice(totalAmount).quantity(1).productColor(color).build();
        em.persist(size);

        Order order = Order.builder().user(buyer).totalAmount(totalAmount).discountAmount(0).usedPoints(0)
                .status(OrderStatus.IN_TRANSIT).build();
        em.persist(order);
        em.persist(OrderShipment.builder().order(order).receiverName("구매자").receiverPhone("010-1111-2222")
                .postalCode("12345").address("서울").courier("CJ").trackingNumber("T-" + seq)
                .status(ShipmentStatus.IN_TRANSIT).build());

        Sale sale = Sale.builder().seller(seller).productSize(size).status(SaleStatus.SELLING).build();
        em.persist(sale);
        em.persist(SaleBid.builder().seller(seller).productSize(size).bidPrice(totalAmount)
                .status(com.fream.back.domain.sale.entity.BidStatus.MATCHED).sale(sale).order(order).build());
        em.persist(OrderBid.builder().user(buyer).productSize(size).bidPrice(totalAmount)
                .status(BidStatus.MATCHED).order(order).sale(sale).build());
        em.flush();
        em.clear();
        return order.getId();
    }

    private List<Point> pointsOf(User u) {
        return em.createQuery("select p from Point p where p.user.id = :uid", Point.class)
                .setParameter("uid", u.getId()).getResultList();
    }

    @Test
    void deliveredOrderGivesBuyerOnePercentPoints() {
        User buyer = user("buyer-v5@test.com");
        User seller = user("seller-v5@test.com");
        Long orderId = orderInTransit(buyer, seller, 123_456);

        new Wiring(ctx).get(OrderShipmentCommandService.class).completeOrder(orderId);
        em.flush();
        em.clear();

        List<Point> points = pointsOf(buyer);
        assertThat(points).hasSize(1);
        assertThat(points.get(0).getAmount()).isEqualTo(1234);
        assertThat(points.get(0).getRemainingAmount()).isEqualTo(1234);
        assertThat(em.find(Order.class, orderId).getStatus()).isEqualTo(OrderStatus.COMPLETED);
    }
}
package com.fream.back.visible.t05;

import org.mockito.Mockito;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.context.ApplicationContext;
import org.springframework.context.ApplicationEvent;
import org.springframework.context.ApplicationEventPublisher;
import org.springframework.context.PayloadApplicationEvent;
import org.springframework.context.annotation.ClassPathScanningCandidateComponentProvider;
import org.springframework.context.event.EventListener;
import org.springframework.core.type.filter.AnnotationTypeFilter;
import org.springframework.stereotype.Component;
import org.springframework.transaction.event.TransactionalEventListener;

import java.lang.reflect.Constructor;
import java.lang.reflect.Field;
import java.lang.reflect.InvocationTargetException;
import java.lang.reflect.Method;
import java.lang.reflect.Modifier;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;

/**
 * 테스트용 객체 조립기.
 *
 * - 리포지토리·EntityManager 등 테스트 컨텍스트(@DataJpaTest)에 있는 빈은 그대로 쓴다.
 * - com.fream.back.domain 아래의 @Service/@Component 클래스는 실제 객체로 생성자 주입해 만든다.
 * - 그 밖의 의존(외부 연동·Redis·WebSocket 등)은 Mockito mock으로 채운다.
 * - ApplicationEventPublisher로 발행한 이벤트는 domain 아래 @EventListener/@TransactionalEventListener 메서드로 즉시 전달한다.
 */
final class Wiring {

    private static final String DOMAIN = "com.fream.back.domain";

    private final ApplicationContext ctx;
    private final Map<Class<?>, Object> instances = new HashMap<>();
    private final Set<Class<?>> building = new HashSet<>();
    private List<Class<?>> listenerClasses;

    Wiring(ApplicationContext ctx) {
        this.ctx = ctx;
        instances.put(ApplicationEventPublisher.class, (ApplicationEventPublisher) this::dispatch);
    }

    <T> Wiring with(Class<T> type, T instance) {
        instances.put(type, instance);
        return this;
    }

    @SuppressWarnings("unchecked")
    <T> T get(Class<T> type) {
        Object existing = instances.get(type);
        if (existing != null) {
            return (T) existing;
        }
        if (type == String.class) {
            return (T) "";
        }
        if (type.isPrimitive()) {
            return (T) defaultPrimitive(type);
        }
        Object bean = ctx.getBeanProvider(type).getIfUnique();
        if (bean != null) {
            return (T) bean;
        }
        Object created;
        if (isDomainComponent(type) && !building.contains(type)) {
            building.add(type);
            try {
                created = construct(type);
            } finally {
                building.remove(type);
            }
        } else {
            created = Mockito.mock(type);
        }
        instances.put(type, created);
        return (T) created;
    }

    private static boolean isDomainComponent(Class<?> t) {
        return t.getName().startsWith(DOMAIN + ".")
                && !t.isInterface()
                && !Modifier.isAbstract(t.getModifiers())
                && org.springframework.core.annotation.AnnotatedElementUtils.hasAnnotation(t, Component.class);
    }

    private Object construct(Class<?> type) {
        try {
            Constructor<?> ctor = null;
            for (Constructor<?> c : type.getDeclaredConstructors()) {
                if (c.isAnnotationPresent(Autowired.class)) {
                    ctor = c;
                }
            }
            if (ctor == null) {
                ctor = java.util.Arrays.stream(type.getDeclaredConstructors())
                        .max(Comparator.comparingInt(Constructor::getParameterCount))
                        .orElseThrow();
            }
            Class<?>[] params = ctor.getParameterTypes();
            Object[] args = new Object[params.length];
            for (int i = 0; i < params.length; i++) {
                args[i] = get(params[i]);
            }
            ctor.setAccessible(true);
            Object obj = ctor.newInstance(args);
            instances.put(type, obj);
            for (Class<?> c = type; c != null && c != Object.class; c = c.getSuperclass()) {
                for (Field f : c.getDeclaredFields()) {
                    if (f.isAnnotationPresent(Autowired.class) && !Modifier.isStatic(f.getModifiers())) {
                        f.setAccessible(true);
                        if (f.get(obj) == null) {
                            f.set(obj, get(f.getType()));
                        }
                    }
                }
            }
            return obj;
        } catch (ReflectiveOperationException e) {
            throw new IllegalStateException("cannot build " + type.getName(), e);
        }
    }

    private void dispatch(Object event) {
        Object payload = (event instanceof PayloadApplicationEvent<?> p) ? p.getPayload() : event;
        for (Class<?> listenerType : listenerClasses()) {
            for (Method m : listenerType.getDeclaredMethods()) {
                boolean listener = m.isAnnotationPresent(EventListener.class)
                        || m.isAnnotationPresent(TransactionalEventListener.class);
                if (!listener || m.getParameterCount() != 1) {
                    continue;
                }
                Class<?> p = m.getParameterTypes()[0];
                Object arg = p.isInstance(payload) ? payload
                        : (event instanceof ApplicationEvent && p.isInstance(event)) ? event : null;
                if (arg == null) {
                    continue;
                }
                try {
                    m.setAccessible(true);
                    m.invoke(get(listenerType), arg);
                } catch (InvocationTargetException e) {
                    Throwable t = e.getTargetException();
                    if (t instanceof RuntimeException re) {
                        throw re;
                    }
                    throw new IllegalStateException(t);
                } catch (IllegalAccessException e) {
                    throw new IllegalStateException(e);
                }
            }
        }
    }

    private List<Class<?>> listenerClasses() {
        if (listenerClasses == null) {
            listenerClasses = new ArrayList<>();
            ClassPathScanningCandidateComponentProvider scanner = new ClassPathScanningCandidateComponentProvider(false);
            scanner.addIncludeFilter(new AnnotationTypeFilter(Component.class));
            scanner.findCandidateComponents(DOMAIN).forEach(bd -> {
                try {
                    Class<?> c = Class.forName(bd.getBeanClassName());
                    for (Method m : c.getDeclaredMethods()) {
                        if (m.isAnnotationPresent(EventListener.class)
                                || m.isAnnotationPresent(TransactionalEventListener.class)) {
                            listenerClasses.add(c);
                            break;
                        }
                    }
                } catch (ClassNotFoundException | LinkageError ignored) {
                    // 로드할 수 없는 후보는 건너뛴다
                }
            });
        }
        return listenerClasses;
    }

    private static Object defaultPrimitive(Class<?> t) {
        if (t == boolean.class) return false;
        if (t == char.class) return '\0';
        if (t == byte.class) return (byte) 0;
        if (t == short.class) return (short) 0;
        if (t == int.class) return 0;
        if (t == long.class) return 0L;
        if (t == float.class) return 0f;
        return 0d;
    }
}
package com.fream.back.domain.user.service.point;

import com.fream.back.domain.user.dto.PointDto;
import com.fream.back.domain.user.entity.Point;
import com.fream.back.domain.user.entity.PointStatus;
import com.fream.back.domain.user.entity.User;
import com.fream.back.domain.user.exception.InsufficientPointsException;
import com.fream.back.domain.user.exception.InvalidPointAmountException;
import com.fream.back.domain.user.exception.UserNotFoundException;
import com.fream.back.domain.user.repository.PointRepository;
import com.fream.back.domain.user.service.query.UserQueryService;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.time.LocalDate;
import java.util.List;

@Slf4j
@Service
@RequiredArgsConstructor
public class PointCommandService {

    private final PointRepository pointRepository;
    private final UserQueryService userQueryService;

    /**
     * 포인트 적립
     */
    @Transactional
    public PointDto.PointResponse addPoint(String email, PointDto.AddPointRequest request) {
        log.info("포인트 적립 시작 - 사용자: {}, 적립액: {}", email, request.getAmount());

        try {
            // 입력값 검증
            validateAddPointRequest(request);

            User user = userQueryService.findByEmail(email);
            if (user == null) {
                throw new UserNotFoundException(email);
            }

            Point point = Point.builder()
                    .user(user)
                    .amount(request.getAmount())
                    .remainingAmount(request.getAmount())
                    .reason(request.getReason())
                    .expirationDate(LocalDate.now().plusDays(90)) // 90일 후 만료
                    .status(PointStatus.AVAILABLE)
                    .build();

            Point savedPoint = pointRepository.save(point);

            log.info("포인트 적립 완료 - 사용자: {}, 적립액: {}, 포인트 ID: {}",
                    email, request.getAmount(), savedPoint.getId());

            return PointDto.PointResponse.from(savedPoint);
        } catch (UserNotFoundException | InvalidPointAmountException e) {
            throw e;
        } catch (Exception e) {
            log.error("포인트 적립 중 예상치 못한 오류 발생 - 사용자: {}, 적립액: {}",
                    email, request.getAmount(), e);
            throw new InvalidPointAmountException("포인트 적립 처리 중 오류가 발생했습니다.");
        }
    }

    /**
     * 포인트 사용
     */
    @Transactional
    public PointDto.UsePointResponse usePoint(String email, PointDto.UsePointRequest request) {
        log.info("포인트 사용 시작 - 사용자: {}, 사용액: {}", email, request.getAmount());

        try {
            // 입력값 검증
            validateUsePointRequest(request);

            User user = userQueryService.findByEmail(email);
            if (user == null) {
                throw new UserNotFoundException(email);
            }

            int pointsToUse = request.getAmount();

            // 가용 포인트 총합 확인
            Integer totalAvailable = pointRepository.getTotalAvailablePoints(user);
            if (totalAvailable == null || totalAvailable < pointsToUse) {
                log.warn("포인트 부족 - 사용자: {}, 필요: {}, 보유: {}",
                        email, pointsToUse, totalAvailable != null ? totalAvailable : 0);
                throw new InsufficientPointsException(pointsToUse, totalAvailable != null ? totalAvailable : 0);
            }

            // 만료 임박 포인트부터 사용
            List<Point> availablePoints = pointRepository.findByUserAndStatusOrderByExpirationDateAsc(user, PointStatus.AVAILABLE);
            int remainingToUse = pointsToUse;
            int totalUsed = 0;

            for (Point point : availablePoints) {
                if (remainingToUse <= 0) break;

                Integer usedAmount = point.use(remainingToUse);
                int used = usedAmount != null ? usedAmount : 0;
                remainingToUse -= used;
                totalUsed += used;

                // 포인트 사용 이유 추가
                if (used > 0) {
                    point.setReason(request.getReason());
                    pointRepository.save(point);
                }
            }

            // 사용 후 남은 총 포인트 계산
            Integer remainingTotal = pointRepository.getTotalAvailablePoints(user);
            if (remainingTotal == null) remainingTotal = 0;

            log.info("포인트 사용 완료 - 사용자: {}, 사용액: {}, 남은 포인트: {}",
                    email, totalUsed, remainingTotal);

            return PointDto.UsePointResponse.builder()
                    .usedPoints(totalUsed)
                    .remainingTotalPoints(remainingTotal)
                    .message("포인트가 성공적으로 사용되었습니다.")
                    .build();
        } catch (UserNotFoundException | InvalidPointAmountException | InsufficientPointsException e) {
            throw e;
        } catch (Exception e) {
            log.error("포인트 사용 중 예상치 못한 오류 발생 - 사용자: {}, 사용액: {}",
                    email, request.getAmount(), e);
            throw new InsufficientPointsException("포인트 사용 처리 중 오류가 발생했습니다.");
        }
    }

    /**
     * 만료된 포인트 처리 (스케줄러에서 호출)
     */
    @Transactional
    public int expirePoints() {
        log.info("만료 포인트 처리 시작");

        try {
            List<Point> expiredPoints = pointRepository.findByStatusAndExpirationDateBefore(
                    PointStatus.AVAILABLE, LocalDate.now());

            for (Point point : expiredPoints) {
                point.expire();
            }

            log.info("만료 포인트 처리 완료 - 만료된 포인트 수: {}", expiredPoints.size());
            return expiredPoints.size();
        } catch (Exception e) {
            log.error("만료 포인트 처리 중 오류 발생", e);
            return 0;
        }
    }

    /**
     * 포인트 적립 요청 검증
     */
    private void validateAddPointRequest(PointDto.AddPointRequest request) {
        if (request == null) {
            throw new InvalidPointAmountException("포인트 적립 요청 데이터가 없습니다.");
        }

        if (request.getAmount() <= 0) {
            throw new InvalidPointAmountException(request.getAmount());
        }

        if (request.getAmount() > 1000000) { // 최대 100만 포인트 적립 제한
            throw new InvalidPointAmountException("한 번에 적립할 수 있는 포인트는 최대 1,000,000점입니다.");
        }

        if (request.getReason() == null || request.getReason().trim().isEmpty()) {
            throw new InvalidPointAmountException("포인트 적립 사유를 입력해주세요.");
        }
    }

    /**
     * 포인트 사용 요청 검증
     */
    private void validateUsePointRequest(PointDto.UsePointRequest request) {
        if (request == null) {
            throw new InvalidPointAmountException("포인트 사용 요청 데이터가 없습니다.");
        }

        if (request.getAmount() <= 0) {
            throw new InvalidPointAmountException(request.getAmount());
        }

        if (request.getReason() == null || request.getReason().trim().isEmpty()) {
            throw new InvalidPointAmountException("포인트 사용 사유를 입력해주세요.");
        }
    }
